import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  Output,
  OnInit,
  OnDestroy
} from '@angular/core';
import { PresentsetupService } from '../../services/presentsetup/presentsetup.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { ActivatedRoute, Router } from '@angular/router';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { LocationStrategy } from '@angular/common';
import {
  presentGetFiles,
  presentScheduleList,
  presentSetupData,
} from '../../interfaces/presentsetup';
import { TableComponent } from '../../../shared/components/myfiles/table/table.component';
import { FilehaderComponent } from '../../../shared/components/myfiles/filehader/filehader.component';
import { MatMenuModule } from '@angular/material/menu';
import { EmptyComponent } from '../../../shared/components/empty/empty.component';
import { MatExpansionModule } from '@angular/material/expansion';
import { PreviewComponent } from '../../../shared/components/myfiles/preview/preview.component';
import { RecentfileComponent } from '../../../shared/components/recentfile/recentfile.component';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { CdkDropList, CdkDrag, moveItemInArray } from '@angular/cdk/drag-drop';
import { HeaderService } from '../../../core/services/header/header.service';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { FilecolumnService } from '../../../shared/services/filecolumn/filecolumn.service';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';

// Derive PresentSType from presentSetupData cSType union type
export const PresentSType: Record<string, presentSetupData['cSType']> = {
  WITNESS: 'W',
  CORE: 'C',
  FILE: 'F',
  EMPTY: ''
};

@Component({
  selector: 'app-core-case',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    TableComponent,
    FilehaderComponent,
    ButtonComponent,
    MatMenuModule,
    MatExpansionModule,
    PreviewComponent,
    RecentfileComponent,
    EmptyComponent,
    MatSelectModule,
    FormsModule,
    CdkDropList,
    CdkDrag,
    IconComponent,
  ],
  templateUrl: './core-case.component.html',
  styleUrl: './core-case.component.scss',
})
export class CoreCaseComponent implements OnInit, OnDestroy {
  // Expose PresentType for template usage
  readonly PresentType = PresentSType;
  @Input() nCaseid: string;
  @Input() nPresentid: string;
  @Input() cSubType: string;

  coreFiles: presentGetFiles[] = [];
  scheduleFiles: presentGetFiles[] = [];
  reqcols: any = {};

  viewlist: any[] = [];

  isLoading: boolean = true;
  presentSession: presentSetupData;

  isPreview: boolean = false;
  scheduleList: presentScheduleList[] = [];

  @Output() OnFileSelected: EventEmitter<any> = new EventEmitter<any>();
  @Output() handleSelectedFileIds: EventEmitter<any> = new EventEmitter<any>();

  @Input() enableFileDrag: boolean = false;
  @Input() isChooser: boolean = false;
  cSortby: string;
  cLastOtype: string = 'flag2';

  constructor(
    private readonly PSservice: PresentsetupService,
    public readonly cm: CommonfunctionService,
    private readonly route: ActivatedRoute,
    private readonly cdr: ChangeDetectorRef,
    private readonly location: LocationStrategy,
    private readonly router: Router,
    private readonly hs: HeaderService,
    private readonly fcs: FilecolumnService,
    private readonly userPermissions: UserPermissionService
  ) {
    this.reqcols = this.fcs.reqcols;
    const paramsObj = this.route.snapshot.params;
    if (Object.keys(paramsObj).length > 0) {
      const decodedParams = JSON.parse(decodeURIComponent(paramsObj['id']));
      this.nPresentid = decodedParams?.nPid ?? null;
      this.nCaseid = decodedParams?.id ?? null;
      this.hs.nCaseid = this.nCaseid;
    }
    // Prevent browser back navigation
    globalThis.history.pushState(null, null, globalThis.location.href);
    this.location.onPopState(() => {
      globalThis.history.pushState(null, null, globalThis.location.href);
    });
    setTimeout(() => this.userPermissions.userPermissionList(this.nCaseid));
  }

  ngOnInit(): void {
    this.reqcols['extra']['view'] = false;
    this.reqcols['index']['view'] = true;
    if (!this.cSubType) {
      this.reqcols['check']['view'] = false;
    }
    (async () => {
      if (this.nCaseid) {
        this.presentSession = await this.PSservice.getRvalue(this.nCaseid);
        if (this.nPresentid) {
          await this.getFiles();
        }
        if (this.cSubType) {
          await this.getScheduleList();
        }
      }
      this.isLoading = false;
      this.cdr.detectChanges();
    })();
  }

  gotoFile() {
    if (!this.nCaseid) return;

    let data = { id: this.nCaseid };

    if (this.nPresentid) {
      data['nPid'] = this.nPresentid;
    }
    this.cm.gotoUrl('/present/choose-docs', data);
  }

  async getFiles(type?: string): Promise<any> {
    const fileList = await this.PSservice.getFiles(this.nPresentid,
      this.cSortby,
      this[this.cLastOtype] ? 'DESC' : 'ASC');
    if (!fileList.length) return;

    const [core, schedule] = fileList.reduce(
      ([coreAcc, scheduleAcc], file) => {
        if (file.cType === 'C') {
          coreAcc.push(file);
        } else {
          scheduleAcc.push(file);
        }
        return [coreAcc, scheduleAcc];
      },
      [[], []]
    );

    if (type === 'C') {
      this.coreFiles = core;
    } else if (type === 'S') {
      this.scheduleFiles = schedule;
    } else {
      this.coreFiles = core;
      this.scheduleFiles = schedule;
    }
    this.isLoading = false;
    this.cdr.detectChanges();
  }



  async sort_array(event, type) {
    const { key, flag } = event;
    this.cLastOtype = flag;
    this[flag] = this[flag] ? !this[flag] : true;
    this.cSortby = key;
    await this.getFiles(type);
    await this.update_serial(type)
  }


  changeTable(event: any, x: any) {
    if (event == 'VIEW') {
      this.viewFile(x);
    }
  }

  handleSelectionEvent() {
    const files1 = this.scheduleFiles
      .filter((a) => !!a['cIscheck'])
      .map((e) => e.nBundledetailid);
    const files2 = this.coreFiles
      .filter((a) => !!a['cIscheck'])
      .map((e) => e.nBundledetailid);
    const files = [...files1, ...files2];

    this.handleSelectedFileIds.emit(files);
    this.cdr.detectChanges();
  }

  async clearSchedule() {
    const res = await this.PSservice.clearSchedule(this.nPresentid);
    if (res.msg == 1) {
      this.coreFiles = [];
      this.scheduleFiles = [];
      this.cdr.detectChanges();
    }
  }

  async submit() {
    if (
      !this.nPresentid ||
      (!this.coreFiles.length && !this.scheduleFiles.length)
    )
      return;



    const dataObj = {
      cStatus: 'I',
      nPresentid: this.nPresentid,
    };

    const res = await this.PSservice.update_status(dataObj);

    if (res?.msg == 1) {
      this.router.navigateByUrl(
        `/individual/doc/${encodeURIComponent(
          JSON.stringify([[], this.nCaseid, this.nPresentid])
        )}`
      );
    }
  }

  recentOutput(event) {
    if (event.event == 'VIEW') {
      this.viewFile(event.data);
    }
  }

  viewFile(x) {
    if (this.isPreview) {
      this.updatePreviewMode(x);
    } else {
      this.isPreview = true;
      this.activateItem(x);
    }
  }

  activateItem(x) {
    if (
      this.viewlist.length === 0 ||
      this.viewlist[0].nBundledetailid !== x.nBundledetailid
    ) {
      x.active = true;
      this.cm.viewlist = [x];
      this.viewlist = this.cm.viewlist;
      this.cdr.detectChanges();
    }
  }

  updatePreviewMode(x) {
    const index = this.viewlist.findIndex(
      (e) => e.nBundledetailid === x.nBundledetailid
    );
    if (index > -1) {
      this.viewlist.splice(index, 1);
    } else {
      this.activateItem(x);
      this.viewlist.forEach((item, idx) => (item['active'] = idx === 0));
    }

    this.cm.viewlist = this.viewlist;
    this.cdr.detectChanges();
  }

  handleSelect(value: string) {
    this.nPresentid = value;
    this.cdr.detectChanges();
    this.getFiles();
  }

  async getScheduleList() {
    this.scheduleList = await this.PSservice.scheduleList(this.nCaseid);
    this.cdr.detectChanges();
  }

  async drop(event: any) {
    if (this.isChooser) {
      return;
    }

    moveItemInArray(
      this.scheduleFiles,
      event.previousIndex,
      event.currentIndex
    );

    await this.update_serial()
    this.cSortby = null;
    this.cLastOtype = 'flag2';
    this.getFiles();
    this.cdr.detectChanges();
  }

  async update_serial(type?: string): Promise<any> {
    if (type === 'C') {
      this.coreFiles.forEach((file, index) => { file.nSerial = index + 1; });
      const jFiles = this.coreFiles.map((e) => ({
        nPDid: e.nPDid,
        nSerial: e.nSerial,
      }));
      return await this.PSservice.files_serial_update({
        nPresentid: this.nPresentid,
        jFiles,
      });
    } else {
      this.scheduleFiles.forEach((file, index) => { file.nSerial = index + 1; });
      const jFiles = this.scheduleFiles.map((e) => ({
        nPDid: e.nPDid,
        nSerial: e.nSerial,
      }));
      return await this.PSservice.files_serial_update({
        nPresentid: this.nPresentid,
        jFiles,
      });
    }
  }

  OnSelected($event: any) {
    this.OnFileSelected.emit($event);
  }

  tableEvent(event: { event: string; data: any }, x: presentGetFiles) {
    if (event['event'] == 'SELECTED') {
      x['cIscheck'] = event['data']['cIscheck'];
      this.cdr.detectChanges();
      this.handleSelectionEvent();
    }
  }

  ngOnDestroy() {
    this.reqcols['index']['view'] = false;
    this.reqcols['check']['view'] = true;
  }
}
